		while (enabled() && retiredHead != 0L) {
			long id = retiredHead;
			int slot = findNamespace(namespaceIds, id);
			if (slot < 0) {
				disabled = true;
				return;
			}
			retiredHead = namespaceNext[slot];
			namespaceNext[slot] = 0L;
			if (retiredHead == 0) {
				retiredTail = 0;
			}
			if (namespaceReferences[slot] == 0L) {
				try {
					consumer.accept(id);
				} catch (RuntimeException | Error failure) {
					enqueueRetirement(slot);
					throw failure;
				}
				removeNamespace(slot);
			} else {
				namespaceState[slot] = 1;
			}
		}
